{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "The bill would require students participating under two Tennessee education provisions to take the same annual TCAP tests, or state-approved successor tests, given to public school students in the same grade or course.",
      "rationale": "The summary conveys the annual testing requirement and, elsewhere, parental responsibility and the disability exemption under § 49-10-1403. However, it describes successor tests as state-approved without identifying the state board of education as the required authorizing body."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Participating eleventh graders would also take the examination given to public school eleventh graders.",
      "rationale": "This identifies the required examination and grade. The subsequent discussion of § 49-10-1403 establishes parental responsibility and the applicable disability exemption."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "Participating students in kindergarten through third grade would take the specified reading screeners during each of the education department’s three annual testing windows.",
      "rationale": "The summary conveys the grades, annual administration windows, and, elsewhere, parental responsibility and the exemption. It does not specify each of the three Tennessee universal reading screeners or the alternative of universal reading screeners approved by the state board of education."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Under the change to § 49-10-1403, parents would be responsible for ensuring that their participating children take these assessments, and the results would have to be reported to the parents.",
      "rationale": "The summary expressly requires reporting participating students’ assessment results to their parents under the identified provision."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "Students with disabilities whose IEPs indicate they would have taken alternate assessments would be exempt from those requirements.",
      "rationale": "The summary conveys the disability exemption, its IEP-based alternate-assessment condition, and its application to the preceding § 49-10-1403 requirements."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "The bill would require students participating under two Tennessee education provisions to take the same annual TCAP tests, or state-approved successor tests, given to public school students in the same grade or course.",
      "rationale": "The summary conveys annual testing matched to public school students and later identifies it as a participation condition under § 49-6-2606(a)(1). It does not identify the state board of education as the required authorizing body for successor tests."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Participating eleventh graders would also take the examination given to public school eleventh graders.",
      "rationale": "The summary identifies the grade and required examination, and its later discussion of § 49-6-2606(a)(1) makes taking these assessments a condition of program participation."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "Participating students in kindergarten through third grade would take the specified reading screeners during each of the education department’s three annual testing windows.",
      "rationale": "The summary conveys the grades and annual testing windows and later states the participation condition. It omits the requirement for each of the three Tennessee universal reading screeners or state-board-approved universal reading screeners."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2025.",
      "rationale": "The summary states the exact effective date."
    }
  ]
}
